import numpy as np
import cv2 as cv

img = np.zeros((512,512,3) , np.uint8)
cv.circle(img, (200, 100), 15 , (0, 0, 255), 10 )
cv.circle(img, (173, 140), 15 , (0, 255, ), 10 )


import numpy as np

points = np.array([
    [200, 100],
    [173, 140],
    [227, 140]
], np.int32)
points1 = np.array([
    [227, 140],
    [210, 120],
    [240, 120],

], np.int32)

points = points.reshape((-1, 1, 2))

cv.polylines(img, [points], True, (0, 255, 0), 1)
cv.fillPoly(img, [points], (0, 0, 0))
cv.circle(img, (227, 140), 15 , (255, 0, 0), 10 )
cv.polylines(img, [points1], True, (0, 255, 0), 1)
cv.fillPoly(img, [points1], (0, 0, 0))
font =cv.FONT_ITALIC
cv.putText(img, 'Open CV' , (290 , 140) , font , 1 , (255 , 255 , 255) , cv.LINE_AA)
cv.imshow("drawing" , img)
k = cv.waitKey(0)
if k == ord('a'):
    cv.destroyAllWindows()